function serviceMinutes(value) { const [hours, minutes] = String(value || '00:00').split(':').map(Number); return hours * 60 + minutes; }

function hasServiceConflict(services, form, currentId) {
  const start = serviceMinutes(form.time);
  const end = serviceMinutes(form.end);
  if (!form.person || !form.date || end <= start) return end <= start;
  return services.some((service) => service.id !== currentId && service.person === form.person && (service.date || '2026-10-29') === form.date && service.state !== 'Cancelado' && start < serviceMinutes(service.end) && end > serviceMinutes(service.time));
}

function ServiceWithClientAddressModal({ record, clients, employees, services = [], onClose, onSave: onSaveRaw }) {
  const initialClient = record?.client || clients[0]?.name || '';
  const initialClientData = clients.find((client) => client.name === initialClient);
  const [form, setForm] = useState({ client: initialClient, person: record?.person || employees[0]?.name || '', type: record?.type || serviceCatalog[0][0], place: record?.place || initialClientData?.address || initialClientData?.location || '', date: record?.date || '2026-10-29', time: record?.time || '09:00', end: record?.end || '11:00', tasks: record?.tasks || serviceCatalog[0][1], recurrence: record?.recurrence || 'Pontual', state: record?.state || 'Planeado' });
  const [formError, setFormError] = useState('');
  const currentServices = services.length ? services : readStored('services', []);
  const selectedClient = clients.find((client) => client.name === form.client);
  const clientAddress = getClientAddress(selectedClient);
  useEffect(() => { setForm((current) => current.place === clientAddress ? current : { ...current, place: clientAddress }); }, [clientAddress]);
  const set = (key) => (event) => setForm((current) => ({ ...current, [key]: event.target.value }));
  const changeClient = (event) => { const clientName = event.target.value; const client = clients.find((item) => item.name === clientName); const address = getClientAddress(client); setForm((current) => ({ ...current, client: clientName, place: address })); };
  const changeType = (event) => { const type = event.target.value; setForm((current) => ({ ...current, type, tasks: serviceCatalog.find(([name]) => name === type)?.[1] || current.tasks })); };
  const submit = (event) => { event.preventDefault(); const next = { ...form, client: selectedClient?.name || form.client, place: clientAddress }; if (hasServiceConflict(services, next, record?.id)) { setFormError('Este funcionário já tem um serviço sobreposto nesse dia. Escolha outro horário ou funcionário.'); return; } setFormError(''); onSave(next); };
  const onSave = (next) => { if (hasServiceConflict(currentServices, next, record?.id)) { window.alert('Este funcionário já tem um serviço sobreposto nesse dia. Escolha outro horário ou funcionário.'); return; } if (serviceMinutes(next.end) <= serviceMinutes(next.time)) { window.alert('A hora de fim tem de ser posterior à hora de início.'); return; } onSaveRaw(next); };
  return <div className="modal-backdrop" onMouseDown={onClose}><div className="modal wide-modal" onMouseDown={(event) => event.stopPropagation()}><div className="modal-head"><div><h2>{record ? 'Editar serviço' : 'Novo serviço'}</h2><p>Escolha o cliente, funcionário, local e tarefas.</p></div><button className="modal-close" onClick={onClose}><X size={19} /></button></div><form onSubmit={(event) => { event.preventDefault(); onSave({ ...form, client: selectedClient?.name || form.client, place: clientAddress }); }}><div className="form-grid"><label>Cliente<select value={form.client} onChange={changeClient} required>{clients.map((client) => <option key={client.name} value={client.name}>{client.name}</option>)}</select>{selectedClient && <small key={selectedClient.name} className="selected-address"><MapPin size={13} /> {clientAddress || 'Morada não definida'}</small>}</label><label>Funcionário<select value={form.person} onChange={set('person')} required>{employees.filter((employee) => employee.status !== 'Inativo' && employee.status !== 'Arquivado').map((employee) => <option key={employee.name} value={employee.name}>{employee.name}</option>)}</select></label><label>Data<input type="date" value={form.date} onChange={set('date')} required /></label><label>Tipo de apoio<select value={form.type} onChange={changeType}>{serviceCatalog.map(([name]) => <option key={name}>{name}</option>)}</select></label><label>Hora de início<input type="time" value={form.time} onChange={set('time')} required /></label><label>Hora de fim<input type="time" value={form.end} onChange={set('end')} required /></label></div><label>Morada do cliente<input key={`${selectedClient?.name || 'sem-cliente'}-${clientAddress}`} value={clientAddress} readOnly required /></label><label>Tarefas a realizar<textarea value={form.tasks} onChange={set('tasks')} required /></label><label>Recorrência<select value={form.recurrence} onChange={set('recurrence')}><option>Pontual</option><option>Diária</option><option>Semanal</option></select></label>{record && <label>Estado<select value={form.state} onChange={set('state')}><option>Planeado</option><option>Em curso</option><option>Concluído</option><option>Cancelado</option></select></label>}<div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>Cancelar</button><button type="submit" className="primary-button"><Check size={17} /> Guardar serviço</button></div></form></div></div>;
}

function CalendarOperationalView({ services, employees, clients, onAdd, onEdit }) {
  const [cursor, setCursor] = useState('2026-10-29');
  const [view, setView] = useState('Semana');
  const [employee, setEmployee] = useState('Todos');
  const [client, setClient] = useState('Todos');
  const dateOf = (value) => new Date(`${value}T12:00:00`);
  const iso = (date) => date.toISOString().slice(0, 10);
  const startOfWeek = (value) => { const date = dateOf(value); const day = date.getDay() || 7; date.setDate(date.getDate() - day + 1); return date; };
  const shift = (value, amount) => { const date = dateOf(value); date.setDate(date.getDate() + amount); return iso(date); };
  const monthLabel = dateOf(cursor).toLocaleDateString('pt-PT', { month: 'long', year: 'numeric' });
  const weekStart = startOfWeek(cursor);
  const days = view === 'Dia' ? [cursor] : view === 'Mês' ? [] : Array.from({ length: 7 }, (_, index) => iso(new Date(weekStart.getTime() + index * 86400000)));
  const filtered = services.filter((service) => (!service.date || (view === 'Mês' ? service.date.slice(0, 7) === cursor.slice(0, 7) : days.includes(service.date || cursor))) && (employee === 'Todos' || service.person === employee) && (client === 'Todos' || service.client === client));
  const move = (amount) => setCursor((value) => view === 'Semana' ? shift(value, amount * 7) : view === 'Mês' ? shift(value, amount * 30) : shift(value, amount));
  const title = view === 'Dia' ? dateOf(cursor).toLocaleDateString('pt-PT', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }) : view === 'Semana' ? `${dateOf(days[0]).toLocaleDateString('pt-PT', { day: 'numeric', month: 'short' })} — ${dateOf(days[6]).toLocaleDateString('pt-PT', { day: 'numeric', month: 'short', year: 'numeric' })}` : monthLabel;
  return <main className="content"><div className="page-intro"><div><h1>Calendário</h1><p>Planeie, filtre e abra qualquer serviço para o editar.</p></div><button className="primary-button" onClick={() => onAdd('Serviço')}><Plus size={18} /> Novo serviço</button></div><div className="calendar-panel"><div className="calendar-toolbar"><button className="filter-button" onClick={() => setCursor('2026-10-29')}>Hoje</button><div className="calendar-nav"><button onClick={() => move(-1)}>‹</button><strong>{title}</strong><button onClick={() => move(1)}>›</button></div><div className="view-switch">{['Dia', 'Semana', 'Mês'].map((item) => <button className={view === item ? 'selected' : ''} onClick={() => setView(item)} key={item}>{item}</button>)}</div></div><div className="calendar-filters"><select className="filter-button native-select" value={employee} onChange={(event) => setEmployee(event.target.value)}><option>Todos</option>{employees.map((item) => <option key={item.name}>{item.name}</option>)}</select><select className="filter-button native-select" value={client} onChange={(event) => setClient(event.target.value)}><option>Todos</option>{clients.map((item) => <option key={item.name}>{item.name}</option>)}</select></div>{view === 'Mês' ? <div className="calendar-month-list">{filtered.length ? filtered.map((service) => <button className="calendar-month-row" key={service.id} onClick={() => onEdit(service)}><strong>{dateOf(service.date || cursor).toLocaleDateString('pt-PT', { weekday: 'short', day: '2-digit', month: '2-digit' })}</strong><span>{service.time} — {service.client}</span><small>{service.person} · {service.type}</small></button>) : <div className="table-empty">Não existem serviços para os filtros selecionados.</div>}</div> : <div className="calendar-day-list">{days.map((day) => <section className="calendar-day-section" key={day}><header><strong>{dateOf(day).toLocaleDateString('pt-PT', { weekday: 'long', day: '2-digit', month: '2-digit' })}</strong><span>{filtered.filter((item) => (item.date || cursor) === day).length} serviços</span></header>{filtered.filter((item) => (item.date || cursor) === day).sort((a, b) => a.time.localeCompare(b.time)).map((service) => <button className="calendar-service-row" key={service.id} onClick={() => onEdit(service)}><time>{service.time} — {service.end}</time><span><strong>{service.client}</strong><small>{service.person} · {service.type}</small></span><Badge tone={service.state === 'Cancelado' ? 'neutral' : service.state === 'Concluído' ? 'green' : 'blue'}>{service.state}</Badge></button>)}{!filtered.some((item) => (item.date || cursor) === day) && <p className="calendar-empty-day">Sem serviços atribuídos.</p>}</section>)}</div>}</div></main>;
}

function App() {
  const [active, setActive] = useState('Dashboard'); const [role, setRole] = useState(() => window.localStorage.getItem('vida-conforto-role') || 'admin'); const [sidebarOpen, setSidebarOpen] = useState(false); const [toast, setToast] = useState(false); const [toastCopy, setToastCopy] = useState({ title: 'Notificação enviada', message: 'A equipa foi informada da alteração.' }); const [services, setServices] = useState(() => readStored('services', initialServices)); const [clientsState, setClientsState] = useState(() => normalizeClients(readStored('clients', clients))); const [employeesState, setEmployeesState] = useState(() => readStored('employees', employees)); const [reports, setReports] = useState(() => readStored('reports', initialReports)); const [timeEntries, setTimeEntries] = useState(() => readStored('time-entries', initialTimeEntries)); const [modalType, setModalType] = useState(null); const [editState, setEditState] = useState(null); const [employeeProfileOpen, setEmployeeProfileOpen] = useState(false); const [employeeReportType, setEmployeeReportType] = useState(null); const [loggedIn, setLoggedIn] = useState(() => window.localStorage.getItem('vida-conforto-session') !== null);
  useEffect(() => { window.localStorage.setItem('vida-conforto-services', JSON.stringify(services)); window.localStorage.setItem('vida-conforto-clients', JSON.stringify(clientsState)); window.localStorage.setItem('vida-conforto-employees', JSON.stringify(employeesState)); window.localStorage.setItem('vida-conforto-reports', JSON.stringify(reports)); window.localStorage.setItem('vida-conforto-time-entries', JSON.stringify(timeEntries)); }, [services, clientsState, employeesState, reports, timeEntries]);
  useEffect(() => { let mounted = true; Promise.all([apiRequest('/clients'), apiRequest('/employees'), apiRequest('/services')]).then(([remoteClients, remoteEmployees, remoteServices]) => { if (!mounted) return; if (remoteClients.length) setClientsState(normalizeClients(remoteClients)); if (remoteEmployees.length) setEmployeesState(remoteEmployees); if (remoteServices.length) setServices(remoteServices); }).catch(() => undefined); return () => { mounted = false; }; }, []);
  useEffect(() => { const timer = window.setTimeout(() => { apiRequest('/sync', { method: 'POST', body: JSON.stringify({ clients: clientsState, employees: employeesState, services }) }).catch(() => undefined); }, 700); return () => window.clearTimeout(timer); }, [clientsState, employeesState, services]);
  const notify = (copy = {}) => { setToastCopy({ title: copy.title || 'Notificação enviada', message: copy.message || 'A equipa foi informada da alteração.' }); setToast(true); if (copy.title === 'Mensagem' || copy.title === 'Ocorrência registada' || copy.title === 'Pedido enviado') { const type = copy.title === 'Mensagem' ? 'Mensagem' : copy.title === 'Ocorrência registada' ? 'Ocorrência' : 'Ausência'; setReports((items) => [{ id: Date.now(), type, title: copy.title, text: copy.message || 'Sem descrição adicional.', employee: 'Maria Silva', date: 'Agora', status: 'Pendente', priority: type === 'Ocorrência' ? 'Normal' : 'Urgente' }, ...items]); } window.setTimeout(() => setToast(false), 3200); };
  const employeeNotify = (copy = {}) => { const reportTypes = { Mensagem: 'Mensagem', 'Ocorrência registada': 'Ocorrência', 'Pedido enviado': 'Ausência' }; if (reportTypes[copy.title]) { setEmployeeReportType(reportTypes[copy.title]); return; } notify(copy); };
  const saveService = (form) => { const base = { ...form, color: editState?.record?.color || 'gray', state: form.state || 'Planeado' }; if (editState?.type === 'Serviço') setServices((items) => items.map((item) => item.id === editState.record.id ? { ...base, id: item.id } : item)); else { const offsets = form.recurrence === 'Semanal' ? [0, 7, 14, 21] : form.recurrence === 'Diária' ? [0, 1, 2, 3, 4, 5, 6] : [0]; const occurrences = offsets.map((offset, index) => { const date = new Date(`${form.date}T00:00:00`); date.setDate(date.getDate() + offset); return { ...base, id: Date.now() + index, date: date.toISOString().slice(0, 10) }; }); setServices((items) => [...items, ...occurrences]); } setModalType(null); setEditState(null); notify({ title: editState?.type === 'Serviço' ? 'Serviço atualizado' : 'Serviço criado', message: form.recurrence === 'Semanal' ? 'Foram criadas 4 ocorrências semanais.' : form.recurrence === 'Diária' ? 'Foram criadas 7 ocorrências diárias.' : 'O serviço foi guardado com sucesso.' }); };
  const cancelService = (service) => { if (!window.confirm(`Cancelar o serviço de ${service.client}?`)) return; setServices((items) => items.map((item) => item.id === service.id ? { ...item, state: 'Cancelado' } : item)); notify({ title: 'Serviço cancelado', message: 'O serviço foi marcado como cancelado.' }); };
  const deleteService = (service) => { if (!window.confirm(`Eliminar definitivamente o serviço de ${service.client}?`)) return; setServices((items) => items.filter((item) => item.id !== service.id)); notify({ title: 'Serviço eliminado', message: 'O serviço foi removido da lista operacional.' }); };
  const updateTimeEntry = (id, status) => { setTimeEntries((items) => items.map((entry) => entry.id === id ? { ...entry, status } : entry)); notify({ title: status === 'Validado' ? 'Horas validadas' : 'Registo rejeitado', message: 'O estado do registo foi atualizado.' }); };
  const deleteTimeEntry = (entry) => { if (!window.confirm(`Eliminar o registo colocado por ${entry.employee}?`)) return; setTimeEntries((items) => items.filter((item) => item.id !== entry.id)); notify({ title: 'Registo eliminado', message: `O lançamento de ${entry.employee} foi removido.` }); };
  const handleTimeEntry = (event) => { setTimeEntries((items) => { const existing = items.find((entry) => entry.employee === event.employee && entry.client === event.client && entry.status === 'Em execução'); if (event.action === 'start') return existing ? items : [{ id: Date.now(), employee: event.employee, client: event.client, date: new Date().toLocaleDateString('pt-PT'), planned: '08:00 — 10:00', actual: `${event.actualStart} — em curso`, duration: 'Em curso', status: 'Em execução' }, ...items]; return items.map((entry) => entry.employee === event.employee && entry.client === event.client && (entry.status === 'Em execução' || entry.status === 'Pendente') ? { ...entry, actual: `${entry.actual.split(' — ')[0]} — ${event.actualEnd}`, duration: 'Registo concluído', status: 'Pendente' } : entry); }); };
  const updateReport = (id, status) => { setReports((items) => items.map((report) => report.id === id ? { ...report, status } : report)); notify({ title: status === 'Aprovado' ? 'Pedido aprovado' : status === 'Rejeitado' ? 'Pedido rejeitado' : 'Reporte atualizado', message: 'O estado foi atualizado para a equipa.' }); };
  const deleteReport = (report) => { if (!window.confirm(`Eliminar o registo enviado por ${report.employee}?`)) return; setReports((items) => items.filter((item) => item.id !== report.id)); notify({ title: 'Registo eliminado', message: 'O reporte foi removido.' }); };
  const saveNew = (form) => { const type = modalType; if (type === 'Cliente') setClientsState((items) => [...items, { ...form, age: form.birthDate ? 'Data registada' : 'A definir', location: form.address || 'Localização por definir', status: form.status || 'Ativo', initials: form.name.split(' ').map((part) => part[0]).slice(0, 2).join('').toUpperCase(), tone: 'sage' }]); if (type === 'Funcionário') setEmployeesState((items) => [...items, { ...form, schedule: form.weeklyHours || 'A definir', status: form.status || 'Ativo', initials: form.name.split(' ').map((part) => part[0]).slice(0, 2).join('').toUpperCase(), tone: 'blue' }]); setModalType(null); notify({ title: `${type} criado`, message: 'O novo registo foi adicionado com sucesso.' }); };
  const login = async (user) => { try { const remote = await apiRequest('/auth/login', { method: 'POST', body: JSON.stringify({ username: user.username, password: user.password || user.username }) }); setLoggedIn(true); setRole(remote.user.role); window.localStorage.setItem('vida-conforto-session', remote.user.username); window.localStorage.setItem('vida-conforto-role', remote.user.role); window.localStorage.setItem('vida-conforto-token', remote.token); } catch { setLoggedIn(true); setRole(user.role); window.localStorage.setItem('vida-conforto-session', user.username); window.localStorage.setItem('vida-conforto-role', user.role); } };
  const logout = () => { setLoggedIn(false); setRole('admin'); setSidebarOpen(false); window.localStorage.removeItem('vida-conforto-session'); window.localStorage.removeItem('vida-conforto-role'); };
  const deleteRecord = (record, type) => { if (!window.confirm(`Arquivar ${record.name}? O histórico será preservado.`)) return; const update = (items) => items.map((item) => item.name === record.name ? { ...item, status: 'Arquivado' } : item); if (type === 'Cliente') setClientsState(update); else setEmployeesState(update); notify({ title: 'Registo arquivado', message: `${record.name} foi arquivado sem apagar o histórico.` }); };
  const saveEdit = (form) => { const { type, record } = editState; const update = (items) => items.map((item) => item.name === record.name ? { ...item, ...form, location: form.address || item.location, schedule: form.weeklyHours || item.schedule, initials: form.name.split(' ').map((part) => part[0]).slice(0, 2).join('').toUpperCase() } : item); if (type === 'Cliente') setClientsState(update); else setEmployeesState(update); setEditState(null); notify({ title: 'Alterações guardadas', message: 'O registo foi atualizado com sucesso.' }); };
  const screen = useMemo(() => { if (active === 'Dashboard') return <DashboardLive services={services} clients={clientsState} employees={employeesState} entries={timeEntries} setActive={setActive} onNotify={notify} onAdd={setModalType} />; if (active === 'Clientes') return <CrudListView type="Clientes" setActive={setActive} onAdd={setModalType} items={clientsState} onEdit={(record) => setEditState({ type: 'Cliente', record })} onDelete={(record) => deleteRecord(record, 'Cliente')} />; if (active === 'Funcionários') return <CrudListView type="Funcionários" setActive={setActive} onAdd={setModalType} items={employeesState} onEdit={(record) => setEditState({ type: 'Funcionário', record })} onDelete={(record) => deleteRecord(record, 'Funcionário')} />; if (active === 'Serviços') return <ServiceAdminView services={services} onAdd={setModalType} onEdit={(record) => setEditState({ type: 'Serviço', record })} onCancel={deleteService} />; if (active === 'Registo de horas') return <HoursManagerView entries={timeEntries} onUpdate={updateTimeEntry} onDelete={deleteTimeEntry} />; if (active === 'Calendário') return <CalendarOperationalView services={services} employees={employeesState} clients={clientsState} onAdd={setModalType} onEdit={(record) => setEditState({ type: 'Serviço', record })} />; if (['Férias e ausências', 'Comunicação', 'Ocorrências'].includes(active)) return <AdminReportManager type={active} reports={reports} onUpdate={updateReport} onDelete={deleteReport} />; if (active === 'Relatórios') return <BasicReportsView services={services} entries={timeEntries} clients={clientsState} employees={employeesState} />; if (active === 'Definições') return <SettingsView />; return <SimpleView type={active} setActive={setActive} onAdd={setModalType} />; }, [active, services, clientsState, employeesState, reports, timeEntries]);
  if (!loggedIn) return <LoginScreen onLogin={login} />;
  if (role === 'employee') return <><EmployeeHome onLogout={logout} onNotify={employeeNotify} onTimeEntry={handleTimeEntry} onEditProfile={() => setEmployeeProfileOpen(true)} /><NotificationToast visible={toast} onClose={() => setToast(false)} title={toastCopy.title} message={toastCopy.message} />{employeeProfileOpen && <EmployeeProfileModal onClose={() => setEmployeeProfileOpen(false)} onSave={(profile) => { setEmployeeProfileOpen(false); notify({ title: 'Perfil atualizado', message: `${profile.name}, as suas informações foram guardadas.` }); }} />}{employeeReportType && <EmployeeReportModal type={employeeReportType} onClose={() => setEmployeeReportType(null)} onSubmit={(message) => { setEmployeeReportType(null); const title = employeeReportType === 'Mensagem' ? 'Mensagem' : employeeReportType === 'Ocorrência' ? 'Ocorrência registada' : 'Pedido enviado'; notify({ title, message }); }} />}</>;
  return <div className="app-shell"><Sidebar active={active} setActive={setActive} open={sidebarOpen} onClose={() => setSidebarOpen(false)} /><div className="app-main"><Topbar onMenu={() => setSidebarOpen(true)} onNotify={notify} onLogout={logout} />{screen}</div>{modalType && (modalType === 'Serviço' ? <ServiceWithClientAddressModal clients={clientsState} employees={employeesState} onClose={() => setModalType(null)} onSave={saveService} /> : <PersonModal type={modalType} onClose={() => setModalType(null)} onSave={saveNew} />)}{editState && (editState.type === 'Serviço' ? <ServiceWithClientAddressModal record={editState.record} clients={clientsState} employees={employeesState} onClose={() => setEditState(null)} onSave={saveService} /> : <PersonModal type={editState.type} record={editState.record} onClose={() => setEditState(null)} onSave={saveEdit} />)}<NotificationToast visible={toast} onClose={() => setToast(false)} title={toastCopy.title} message={toastCopy.message} /></div>;
}

createRoot(document.getElementById('root')).render(<App />);
